<?php
require_once __DIR__.'/../../includes/accounting_ui.php';$id=(int)($_GET['id']??0);try{$p=$ac->record('ac_payments',$id);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
acHandle(function()use($ac,$id){$ac->reversePayment($id,$_POST['date']??'',$_POST['reason']??'',!empty($_POST['confirm']));},'receipt',['id'=>$id]);
$p=$ac->record('ac_payments',$id);$method=$ac->record('ac_methods',(int)$p['method_id']);$schoolInfo=$ac->one('SELECT * FROM schools WHERE id=?',[$school]);$received=$ac->one('SELECT full_name FROM users WHERE id=?',[$p['received_by']]);$allocations=$ac->rows('SELECT a.*,i.number FROM ac_allocations a JOIN ac_invoices i ON i.id=a.invoice_id WHERE a.payment_id=? AND i.school_id=?',[$id,$school]);ob_start();
?>
<button class="btn btn-primary mb-3 no-print" data-erp-click="accounting-receipt-action-0" data-erp-click-args="<?= schoolPageActionArgs("accounting-receipt",[]) ?>">Print / Save receipt PDF</button>
<article class="ac-document"><header class="ac-document-header"><?php if($schoolInfo['logo']): ?><img src="<?= APP_URL ?>/uploads/<?= rawurlencode(basename($schoolInfo['logo'])) ?>" alt="School logo"><?php endif; ?><div><h2><?= sanitize($schoolInfo['name_en']) ?></h2><p><?= sanitize($schoolInfo['address']??'') ?></p></div></header><h3><?= $p['status']==='reversed'?'REVERSED PAYMENT — receipt cancelled':'PAYMENT RECEIPT' ?> <?= sanitize($p['number']) ?></h3><p>Date: <?= sanitize(schoolDateLabel($p['payment_date'])) ?><br>Student / customer: <strong><?= sanitize($p['customer_name']) ?></strong><br>Method: <?= sanitize($method['name']) ?><br>Reference: <?= sanitize($p['reference']??'') ?></p><h2><?= acMoney((int)$p['amount_minor']) ?></h2><p><?= sanitize(acWords((int)$p['amount_minor'])) ?></p><table><thead><tr><th>Invoice</th><th>Amount allocated</th></tr></thead><tbody><?php $allocated=0;foreach($allocations as $r):$allocated+=(int)$r['amount_minor']; ?><tr><td><?= sanitize($r['number']) ?></td><td><?= acMoney((int)$r['amount_minor']) ?></td></tr><?php endforeach; ?></tbody></table><p>Received as advance: <?= acMoney((int)$p['amount_minor']-$allocated) ?></p><?php if($p['student_id']): ?><p>Current account outstanding: <?= acMoney($ac->outstanding((int)$p['student_id'])) ?> · Available advance: <?= acMoney($ac->advanceBalance((int)$p['student_id'])) ?></p><?php endif; ?><p>Received by: <?= sanitize($received['full_name']??'') ?><br>Remarks: <?= sanitize($p['remarks']??'') ?></p><footer class="mt-5"><?= printUserSignature($db,(int)$school,(int)$p['received_by'],'Cashier') ?></footer></article>
<?php if($ac->can('reverse')&&$p['status']==='posted'): ?><details class="no-print mt-4"><summary>Reverse payment (administrator only)</summary><?php acForm('reverse');acInput('date','Reversal date',date('Y-m-d'),'date');acInput('reason','Correction reason'); ?><div class="alert alert-warning">The original payment and receipt are retained as reversed. Invoice balances reopen. Advances already spent must be restored first.</div><label><input type="checkbox" required name="confirm" value="1"> Confirm this reversal</label><?php acSubmit('Reverse payment'); ?></details><?php endif; ?>
<?php acRender('Payment receipt',ob_get_clean());
